/** Generated code controls for one output. */
export type JsGeneratedCodeOptions = {
    /** Whether to emit object shorthand properties. */
    readonly objectShorthand?: boolean;
    /** Whether to preserve reserved names as properties. */
    readonly reservedNamesAsProps?: boolean;
};

export const JsGeneratedCodeOptions = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: JsGeneratedCodeOptions): void {
        encodeJsGeneratedCodeOptions(writer, value);
    },

    /** Decode one JsGeneratedCodeOptions. */
    decode(reader: BinaryReader): JsGeneratedCodeOptions {
        return decodeJsGeneratedCodeOptions(reader);
    },

    /** Return this value as JSON. */
    toJson(value: JsGeneratedCodeOptions): Json {
        return toJsonJsGeneratedCodeOptions(value);
    },

    /** Return one JsGeneratedCodeOptions from one JSON value. */
    fromJson(value: Json): JsGeneratedCodeOptions {
        return fromJsonJsGeneratedCodeOptions(value);
    },
};

/** Encode one JsGeneratedCodeOptions. */
export function encodeJsGeneratedCodeOptions(writer: BinaryWriter, value: JsGeneratedCodeOptions): void {
    writer.writeOption(value.objectShorthand, (value0) => {
        writer.writeBool(value0);
    });
    writer.writeOption(value.reservedNamesAsProps, (value1) => {
        writer.writeBool(value1);
    });
}

/** Decode one JsGeneratedCodeOptions. */
export function decodeJsGeneratedCodeOptions(reader: BinaryReader): JsGeneratedCodeOptions {
    const objectShorthand = reader.readOption(() => reader.readBool());
    const reservedNamesAsProps = reader.readOption(() => reader.readBool());

    return {
        ...(objectShorthand === undefined ? {} : { objectShorthand }),
        ...(reservedNamesAsProps === undefined ? {} : { reservedNamesAsProps }),
    };
}

/** Return one JSON value for one JsGeneratedCodeOptions. */
export function toJsonJsGeneratedCodeOptions(value: JsGeneratedCodeOptions): Json {
    return {
        ...(value.objectShorthand === undefined ? {} : { objectShorthand: value.objectShorthand }),
        ...(value.reservedNamesAsProps === undefined ? {} : { reservedNamesAsProps: value.reservedNamesAsProps }),
    };
}

/** Return one JsGeneratedCodeOptions from one JSON value. */
export function fromJsonJsGeneratedCodeOptions(value: Json): JsGeneratedCodeOptions {
    const object = jsonObject(value);

    return {
        objectShorthand: jsonOptional(object, "objectShorthand", (value) => jsonBool(value)),
        reservedNamesAsProps: jsonOptional(object, "reservedNamesAsProps", (value) => jsonBool(value)),
    };
}

